 "content": "def transform(grid):
    """Stamp the marker pattern wherever the same shape occupies zeros."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker_colors = {v for row in grid for v in row if v not in (0, 1, 6)}
    if not marker_colors:
        # ARC instances use the marked shape as the sole non-background color.
        marker_colors = {v for row in grid for v in row if v not in (0, 6)}
    marker = next(iter(marker_colors))
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    pattern = [(r-r0, c-c0) for r, c in points]
    ph = max(r for r, c in pattern) + 1
    pw = max(c for r, c in pattern) + 1
    for top in range(h - ph + 1):
        for left in range(w - pw + 1):
            if all(grid[top+dr][left+dc] == 0 for dr, dc in pattern):
                for dr, dc in pattern:
                    out[top+dr][left+dc] = marker
    return out
